// skid_buffer: register slice for one valid/ready stream.
// Implements microarchitecture.md (two registers: output and skid).
// Every output is a flop or the inverse of one; inputs reach only next state.
`timescale 1ns/1ps
`default_nettype none

module skid_buffer #(
    parameter integer WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst_n,
    input  wire             s_valid,
    output wire             s_ready,
    input  wire [WIDTH-1:0] s_data,
    output reg              m_valid,
    input  wire             m_ready,
    output reg  [WIDTH-1:0] m_data
);

    reg             skid_valid;
    reg [WIDTH-1:0] skid_data;

    // Output register may load on this edge.
    wire m_free = ~m_valid | m_ready;
    // Upstream transfer on this edge.
    wire s_fire = s_valid & ~skid_valid;

    assign s_ready = ~skid_valid;

    reg             m_valid_nxt;
    reg             skid_valid_nxt;
    reg             m_load;
    reg             skid_load;
    reg [WIDTH-1:0] m_data_nxt;

    // Next state (microarchitecture.md section 3).
    always @(*) begin
        m_valid_nxt    = m_valid;
        skid_valid_nxt = skid_valid;
        m_load         = 1'b0;
        skid_load      = 1'b0;
        m_data_nxt     = s_data;
        if (m_free) begin
            if (skid_valid) begin
                // The skid beat moves to the output register.
                m_valid_nxt    = 1'b1;
                m_load         = 1'b1;
                m_data_nxt     = skid_data;
                skid_valid_nxt = 1'b0;
            end else begin
                // s_ready is high: the offered beat (if any) loads directly.
                m_valid_nxt = s_valid;
                m_load      = s_valid;
            end
        end else if (s_fire) begin
            // Output stalled: the accepted beat goes to the skid register.
            skid_valid_nxt = 1'b1;
            skid_load      = 1'b1;
        end
    end

    // Control state, synchronous active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            m_valid    <= 1'b0;
            skid_valid <= 1'b0;
        end else begin
            m_valid    <= m_valid_nxt;
            skid_valid <= skid_valid_nxt;
        end
    end

    // Data registers: not reset, load only in their control's row.
    always @(posedge clk) begin
        if (m_load) begin
            m_data <= m_data_nxt;
        end
        if (skid_load) begin
            skid_data <= s_data;
        end
    end

`ifdef FORMAL
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    // Reset on the first cycle; nothing is assumed about sender or receiver.
    always @(*) if (!f_past_valid) assume(!rst_n);

    // Port-level model: a queue of up to two beats, moved only by handshakes.
    reg [1:0]       f_count;
    reg [WIDTH-1:0] f_q0;
    reg [WIDTH-1:0] f_q1;
    wire f_in  = s_valid && s_ready;
    wire f_out = m_valid && m_ready;

    always @(posedge clk) begin
        if (!rst_n) begin
            f_count <= 2'd0;
        end else begin
            case ({f_in, f_out})
                2'b10: begin
                    if (f_count == 2'd0) f_q0 <= s_data;
                    else                 f_q1 <= s_data;
                    f_count <= f_count + 2'd1;
                end
                2'b01: begin
                    f_q0    <= f_q1;
                    f_count <= f_count - 2'd1;
                end
                2'b11: begin
                    if (f_count == 2'd1) begin
                        f_q0 <= s_data;
                    end else begin
                        f_q0 <= f_q1;
                        f_q1 <= s_data;
                    end
                end
                default: begin
                end
            endcase
        end
    end

    always @(*) begin
        if (f_past_valid) begin
            assert(f_count <= 2'd2);
            assert(m_valid == (f_count != 2'd0));
            assert(s_ready == (f_count != 2'd2));
            assert(!skid_valid || m_valid);
            if (m_valid)    assert(m_data == f_q0);
            if (skid_valid) assert(skid_data == f_q1);
        end
    end

    // Hold: a stalled beat stays offered with the same data.
    always @(posedge clk) begin
        if (f_past_valid && $past(rst_n) && $past(m_valid) && !$past(m_ready)) begin
            assert(m_valid);
            assert(m_data == $past(m_data));
        end
    end

    // Reset values.
    always @(posedge clk) begin
        if (f_past_valid && !$past(rst_n)) begin
            assert(!m_valid);
            assert(s_ready);
            assert(!skid_valid);
        end
    end

    reg f_was_full;
    initial f_was_full = 1'b0;
    always @(posedge clk) begin
        if (!rst_n)          f_was_full <= 1'b0;
        else if (skid_valid) f_was_full <= 1'b1;
    end

    always @(posedge clk) begin
        if (f_past_valid && rst_n) begin
            cover(m_valid && !m_ready);   // stall
            cover(skid_valid);            // full slice
            cover(f_was_full && !m_valid);// drain after full
        end
    end

    always @(posedge clk) begin
        if (f_past_valid && $past(rst_n) && rst_n)
            cover($past(f_in && f_out) && f_in && f_out); // full throughput
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
