// skid_buffer_tb: self-checking testbench, lanes at WIDTH 8 and WIDTH 1.
`timescale 1ns/1ps
`default_nettype none

`define CHECK(cond, msg) \
    begin \
        if (cond) begin \
            passed = passed + 1; \
        end else begin \
            failed = failed + 1; \
            $error msg; \
        end \
    end

module skid_buffer_tb;
    reg        clk;
    reg        rst_n;
    reg        s_valid;
    reg        m_ready;
    reg  [7:0] s_data8;
    wire       s_data1;
    wire       s_ready8;
    wire       m_valid8;
    wire [7:0] m_data8;
    wire       s_ready1;
    wire       m_valid1;
    wire       m_data1;

    assign s_data1 = s_data8[0];

    skid_buffer #(.WIDTH(8)) dut8 (
        .clk(clk), .rst_n(rst_n),
        .s_valid(s_valid), .s_ready(s_ready8), .s_data(s_data8),
        .m_valid(m_valid8), .m_ready(m_ready), .m_data(m_data8)
    );

    skid_buffer #(.WIDTH(1)) dut1 (
        .clk(clk), .rst_n(rst_n),
        .s_valid(s_valid), .s_ready(s_ready1), .s_data(s_data1),
        .m_valid(m_valid1), .m_ready(m_ready), .m_data(m_data1)
    );

    integer passed;
    integer failed;
    integer mcount;
    reg [7:0] mq0;
    reg [7:0] mq1;
    reg       model_known;
    reg [7:0] next_data;
    reg [7:0] exp_out;
    integer accepted;
    integer delivered;
    integer n_full;
    integer n_stall;
    integer n_thru;
    reg       c_rst;
    reg       c_in;
    reg       c_out;
    reg       c_hold;
    reg [7:0] c_sdata;
    reg [7:0] c_mdata8;
    reg       c_mdata1;
    reg       hold_pending;
    reg [7:0] hold_d8;
    reg       hold_d1;
    reg       last_in;
    reg       last_out;
    reg [8*64-1:0] nonce;
    integer i;
    integer j;
    integer r;
    reg sv;
    reg mr;

    initial begin
        clk = 1'b0;
        forever #5 clk = ~clk;
    end

    // Outputs against the model; called with the DUT stable (after negedge).
    task check_outputs;
        begin
            if (model_known) begin
                `CHECK(m_valid8 == (mcount != 0), ("m_valid8=%b but model holds %0d beats", m_valid8, mcount))
                `CHECK(m_valid1 == (mcount != 0), ("m_valid1=%b but model holds %0d beats", m_valid1, mcount))
                `CHECK(s_ready8 == (mcount != 2), ("s_ready8=%b but model holds %0d beats", s_ready8, mcount))
                `CHECK(s_ready1 == (mcount != 2), ("s_ready1=%b but model holds %0d beats", s_ready1, mcount))
                if (mcount != 0) begin
                    `CHECK(m_data8 == mq0, ("m_data8=%h, expected oldest beat %h", m_data8, mq0))
                    `CHECK(m_data1 == mq0[0], ("m_data1=%b, expected %b", m_data1, mq0[0]))
                end
                if (hold_pending) begin
                    `CHECK(m_valid8 == 1'b1 && m_data8 == hold_d8, ("hold: stalled beat %h changed to %h (valid %b)", hold_d8, m_data8, m_valid8))
                    `CHECK(m_valid1 == 1'b1 && m_data1 == hold_d1, ("hold: W1 stalled beat changed"))
                end
            end
        end
    endtask

    // Flip m_ready, s_valid and s_data for 1 ns: no output may move.
    task glitch_check;
        reg       sv0;
        reg       mr0;
        reg [7:0] sd0;
        reg       sr8;
        reg       sr1;
        reg       mv8;
        reg       mv1;
        reg [7:0] md8;
        reg       md1;
        begin
            if (model_known) begin
                sv0 = s_valid; mr0 = m_ready; sd0 = s_data8;
                sr8 = s_ready8; sr1 = s_ready1;
                mv8 = m_valid8; mv1 = m_valid1;
                md8 = m_data8;  md1 = m_data1;
                s_valid = ~sv0; m_ready = ~mr0; s_data8 = ~sd0;
                #1;
                `CHECK(s_ready8 == sr8 && s_ready1 == sr1, ("s_ready moved with m_ready/s_valid inside a cycle"))
                `CHECK(m_valid8 == mv8 && m_valid1 == mv1, ("m_valid moved with inputs inside a cycle"))
                if (mv8) begin
                    `CHECK(m_data8 == md8 && m_data1 == md1, ("m_data moved with inputs inside a cycle"))
                end
                s_valid = sv0; m_ready = mr0; s_data8 = sd0;
                #1;
            end else begin
                #2;
            end
        end
    endtask

    // Model step for the edge just taken, from values captured before it.
    task model_update;
        begin
            last_in = 1'b0;
            last_out = 1'b0;
            hold_pending = 1'b0;
            if (!c_rst) begin
                mcount = 0;
                exp_out = next_data;
                model_known = 1'b1;
            end else if (model_known) begin
                last_in = c_in;
                last_out = c_out;
                if (c_out) begin
                    `CHECK(c_mdata8 == exp_out, ("order: delivered %h, expected %h", c_mdata8, exp_out))
                    `CHECK(c_mdata1 == exp_out[0], ("order W1: delivered %b, expected %b", c_mdata1, exp_out[0]))
                    exp_out = exp_out + 8'd1;
                    delivered = delivered + 1;
                end
                if (c_in) begin
                    next_data = next_data + 8'd1;
                    accepted = accepted + 1;
                end
                if (c_hold) begin
                    hold_pending = 1'b1;
                    hold_d8 = c_mdata8;
                    hold_d1 = c_mdata1;
                    n_stall = n_stall + 1;
                end
                if (c_in && c_out) n_thru = n_thru + 1;
                if (c_in && !c_out) begin
                    if (mcount == 0) mq0 = c_sdata;
                    else             mq1 = c_sdata;
                    mcount = mcount + 1;
                end else if (!c_in && c_out) begin
                    mq0 = mq1;
                    mcount = mcount - 1;
                end else if (c_in && c_out) begin
                    if (mcount == 1) begin
                        mq0 = c_sdata;
                    end else begin
                        mq0 = mq1;
                        mq1 = c_sdata;
                    end
                end
                if (mcount == 2) n_full = n_full + 1;
            end
        end
    endtask

    // Called just after a negedge with inputs set; returns at the next negedge.
    task do_cycle;
        begin
            #1;
            check_outputs;
            glitch_check;
            c_rst    = rst_n;
            c_in     = s_valid & s_ready8;
            c_out    = m_valid8 & m_ready;
            c_sdata  = s_data8;
            c_mdata8 = m_data8;
            c_mdata1 = m_data1;
            c_hold   = rst_n & m_valid8 & ~m_ready;
            @(posedge clk);
            model_update;
            @(negedge clk);
        end
    endtask

    // Sender offers counting data only when it will be taken, garbage otherwise.
    task drive;
        input dsv;
        input dmr;
        integer rr;
        begin
            rr = $random;
            s_valid = dsv;
            m_ready = dmr;
            if (dsv && s_ready8 == 1'b1 && model_known)
                s_data8 = next_data;
            else
                s_data8 = rr[7:0];
        end
    endtask

    initial begin
        passed = 0; failed = 0;
        accepted = 0; delivered = 0;
        n_full = 0; n_stall = 0; n_thru = 0;
        mcount = 0; mq0 = 8'd0; mq1 = 8'd0;
        model_known = 1'b0;
        next_data = 8'd0; exp_out = 8'd0;
        hold_pending = 1'b0; hold_d8 = 8'd0; hold_d1 = 1'b0;
        last_in = 1'b0; last_out = 1'b0;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = {64{8'h00}};

        rst_n = 1'b0; s_valid = 1'b0; m_ready = 1'b0; s_data8 = 8'd0;
        @(negedge clk);

        // 1. Reset values.
        drive(1'b0, 1'b0); do_cycle;
        drive(1'b1, 1'b0); do_cycle;
        rst_n = 1'b1;
        `CHECK(m_valid8 == 1'b0 && m_valid1 == 1'b0, ("reset: m_valid not low"))
        `CHECK(s_ready8 == 1'b1 && s_ready1 == 1'b1, ("reset: s_ready not high"))
        drive(1'b0, 1'b1); do_cycle;
        drive(1'b0, 1'b0); do_cycle;
        `CHECK(m_valid8 == 1'b0 && s_ready8 == 1'b1, ("idle after reset: outputs moved"))

        // 2. One-cycle latency.
        drive(1'b1, 1'b1);
        `CHECK(m_valid8 == 1'b0 && s_ready8 == 1'b1, ("latency: slice not empty before the beat"))
        do_cycle;
        `CHECK(last_in == 1'b1, ("latency: beat not accepted"))
        `CHECK(m_valid8 == 1'b1 && m_data8 == exp_out, ("latency: beat not offered one cycle after acceptance"))
        drive(1'b0, 1'b1); do_cycle;
        `CHECK(last_out == 1'b1, ("latency: beat not taken"))
        `CHECK(m_valid8 == 1'b0, ("latency: slice not empty after the beat left"))

        // 3. Full throughput.
        drive(1'b1, 1'b1); do_cycle;
        for (i = 0; i < 64; i = i + 1) begin
            drive(1'b1, 1'b1);
            `CHECK(s_ready8 == 1'b1 && m_valid8 == 1'b1, ("throughput: not ready/valid at beat %0d", i))
            do_cycle;
            `CHECK(last_in == 1'b1 && last_out == 1'b1, ("throughput: bubble at beat %0d", i))
        end
        drive(1'b0, 1'b1); do_cycle;
        `CHECK(m_valid8 == 1'b0 && exp_out == next_data, ("throughput: stream did not drain"))

        // 4. Stall with one and two beats held.
        drive(1'b1, 1'b0);
        `CHECK(s_ready8 == 1'b1 && m_valid8 == 1'b0, ("stall: not empty at start"))
        do_cycle;
        `CHECK(last_in == 1'b1, ("stall: first beat not accepted"))
        drive(1'b1, 1'b0);
        `CHECK(s_ready8 == 1'b1 && s_ready1 == 1'b1 && m_valid8 == 1'b1, ("stall: one held, second beat must be accepted"))
        do_cycle;
        `CHECK(last_in == 1'b1 && last_out == 1'b0, ("stall: second beat not accepted"))
        `CHECK(s_ready8 == 1'b0 && s_ready1 == 1'b0, ("stall: two held, s_ready must be low"))
        drive(1'b1, 1'b0); do_cycle;
        `CHECK(last_in == 1'b0, ("stall: third beat accepted with two held"))
        drive(1'b1, 1'b0); do_cycle;
        `CHECK(last_in == 1'b0 && mcount == 2, ("stall: slice did not stay full"))

        // 5. Ready rises: every beat out, in order, once.
        drive(1'b0, 1'b1);
        `CHECK(s_ready8 == 1'b0, ("drain: s_ready high while full"))
        do_cycle;
        `CHECK(last_out == 1'b1, ("drain: first beat not taken"))
        `CHECK(s_ready8 == 1'b1 && m_valid8 == 1'b1, ("drain: s_ready did not rise after a beat left"))
        drive(1'b0, 1'b1); do_cycle;
        `CHECK(last_out == 1'b1 && m_valid8 == 1'b0, ("drain: second beat not taken"))
        `CHECK(exp_out == next_data, ("drain: beats lost or duplicated"))

        // 6. Reset with beats held.
        drive(1'b1, 1'b0); do_cycle;
        drive(1'b1, 1'b0); do_cycle;
        `CHECK(m_valid8 == 1'b1 && s_ready8 == 1'b0, ("reset test: slice not full"))
        rst_n = 1'b0;
        drive(1'b1, 1'b1); do_cycle;
        rst_n = 1'b1;
        `CHECK(m_valid8 == 1'b0 && s_ready8 == 1'b1 && m_valid1 == 1'b0 && s_ready1 == 1'b1, ("reset with beats held: not empty"))
        drive(1'b0, 1'b1); do_cycle;
        `CHECK(last_out == 1'b0 && m_valid8 == 1'b0, ("reset with beats held: a dropped beat came out"))

        // 7. Random traffic with varying bias and rare resets.
        for (i = 0; i < 4000; i = i + 1) begin
            r = $random;
            case (i / 1000)
                0: begin sv = r[0]; mr = r[1]; end
                1: begin sv = (r[1:0] != 2'b00); mr = (r[3:2] == 2'b00); end
                2: begin sv = (r[1:0] == 2'b00); mr = (r[3:2] != 2'b00); end
                default: begin sv = (r[1:0] != 2'b00); mr = (r[3:2] != 2'b00); end
            endcase
            rst_n = (r[13:4] != 10'd0);
            drive(sv, mr);
            do_cycle;
        end
        rst_n = 1'b1;

        // 8. Drain.
        j = 0;
        while (mcount != 0 && j < 10) begin
            drive(1'b0, 1'b1); do_cycle;
            j = j + 1;
        end
        drive(1'b0, 1'b0); do_cycle;
        `CHECK(mcount == 0 && m_valid8 == 1'b0 && m_valid1 == 1'b0, ("drain: slice not empty at end"))
        `CHECK(s_ready8 == 1'b1 && s_ready1 == 1'b1, ("drain: s_ready not high at end"))
        `CHECK(exp_out == next_data, ("drain: accepted and delivered beats differ"))

        // Coverage goals reached by the stimulus.
        `CHECK(n_full > 0, ("coverage: slice never full"))
        `CHECK(n_stall > 0, ("coverage: no stall"))
        `CHECK(n_thru > 0, ("coverage: no simultaneous in/out"))
        `CHECK(delivered > 1000, ("coverage: too little traffic (%0d beats)", delivered))

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`default_nettype wire
